pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val) internal {
        bool reverted;
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(_val) {} catch { return; }
        uint256 observed;
        try c.MinSum() returns (uint256 __r) { observed = __r; } catch { return; }
        assertTrue(!reverted && observed == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
